begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public;
select plan(15);
insert into auth.users (id, aud, role, email, encrypted_password, email_confirmed_at, created_at, updated_at, raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous) values ('b1100000-0000-0000-0000-000000000001', 'authenticated', 'authenticated', 'bia@onze.test', '', now(), now(), now(), '{}', '{}', false, false);
insert into public.workspaces (id, kind, name) values ('b1110000-0000-0000-0000-000000000001', 'empresa', 'Norte Onze');
insert into public.workspace_memberships (workspace_id, user_id, role, active) values ('b1110000-0000-0000-0000-000000000001', 'b1100000-0000-0000-0000-000000000001', 'member', true);
insert into private.agent_conversations (id, workspace_id, owner_id, kind) values ('b1120000-0000-0000-0000-000000000001', 'b1110000-0000-0000-0000-000000000001', 'b1100000-0000-0000-0000-000000000001', 'coordenada');
insert into private.agent_runs (id, workspace_id, conversation_id, requested_by, client_request_id, request_text, status, started_at) values ('b1130000-0000-0000-0000-000000000001', 'b1110000-0000-0000-0000-000000000001', 'b1120000-0000-0000-0000-000000000001', 'b1100000-0000-0000-0000-000000000001', gen_random_uuid(), 'Monte uma Sequência', 'running', now());
create function pg_temp.entrar_como(p uuid) returns void language sql as $$ select set_config('request.jwt.claim.sub', p::text, true), set_config('request.jwt.claim.role', 'authenticated', true) $$;
create function pg_temp.agente(p text) returns uuid language sql as $$ select id from private.agents where workspace_id = 'b1110000-0000-0000-0000-000000000001' and specialty = p and kind = 'padrao' $$;
create temporary table ids (k text primary key, id uuid) on commit drop;
create function pg_temp.id(p text) returns uuid language sql as $$ select id from ids where k = p $$;
create function pg_temp.passos() returns jsonb language sql as $$ select '[{"esperaEmDias": 0, "assunto": "Oi {{primeiro_nome}}", "corpo": "Vi a {{empresa}} contratando."}]'::jsonb $$;
create function pg_temp.ler(p uuid) returns jsonb language sql as $$ select public.agent_read_sequence_contacts('b1130000-0000-0000-0000-000000000001', p, pg_temp.id('alfa')) $$;
create function pg_temp.propor(p uuid) returns table (approval_id uuid, outcome text, account_name text) language sql as $$ select * from public.agent_propose_sequence('b1130000-0000-0000-0000-000000000001', p, pg_temp.id('alfa'), array[pg_temp.id('maria')], pg_temp.passos(), 'Sinal') $$;
create function pg_temp.modelo(p uuid) returns text language sql as $$ select coalesce(template_id::text, '(nenhum)') || '|' || outcome from public.agent_suggest_althius_sequence_template('b1130000-0000-0000-0000-000000000001', p, pg_temp.id('alfa')) $$;
select pg_temp.entrar_como('b1100000-0000-0000-0000-000000000001');
insert into ids select 'alfa', id from public.save_target_account('b1110000-0000-0000-0000-000000000001', 'Alfa', 'https://alfa.onze.test');
insert into ids select 'maria', id from public.create_contact(pg_temp.id('alfa'), 'Maria Souza', 'Diretora', 'maria@alfa.onze.test');
select ok((select not has_function_privilege('authenticated', 'public.agent_propose_sequence(uuid, uuid, uuid, uuid[], jsonb, text)', 'execute')), 'RPCs da Sequência continuam só do servidor');
select ok((select private.agent_can_propose_sequence('b1110000-0000-0000-0000-000000000001', pg_temp.agente('rhetor'))), 'Rhetor pode propor');
select ok((select not private.agent_can_propose_sequence('b1110000-0000-0000-0000-000000000001', pg_temp.agente('scopus'))), 'Scopus não pode propor');
select is((select jsonb_agg(c ->> 'nome') from jsonb_array_elements(pg_temp.ler(pg_temp.agente('rhetor')) -> 'contatos') c), '["Maria Souza"]'::jsonb, 'Rhetor lê Contatos');
select throws_ok(format($$select pg_temp.ler(%L)$$, pg_temp.agente('scopus')), '42501', 'sequence: the agent has no permission to propose sequences', 'Scopus não lê Contatos');
select throws_ok(format($$select * from pg_temp.propor(%L)$$, pg_temp.agente('scopus')), '42501', 'sequence: the agent has no permission to propose sequences', 'Scopus não propõe');
select throws_ok(format($$select pg_temp.modelo(%L)$$, pg_temp.agente('scopus')), '42501', 'sequence: the agent has no permission to propose sequences', 'Scopus não sugere modelo');
select lives_ok(format($$select * from pg_temp.propor(%L)$$, pg_temp.agente('rhetor')), 'Rhetor propõe Sequência');
select is((select count(*)::integer from private.approvals where category = 'sequencia'), 1, 'a proposta do Rhetor nasce pendente');
select lives_ok(format($$select pg_temp.modelo(%L)$$, pg_temp.agente('rhetor')), 'Rhetor sugere modelo da Althius');
select ok((select not private.agent_can_propose_sequence('b1110000-0000-0000-0000-000000000001', (select id from private.agents where workspace_id = 'b1110000-0000-0000-0000-000000000001' and specialty = 'ethos' and kind = 'padrao'))), 'Ethos não pode propor');
select ok((select count(*)::integer from private.agent_step_permissions where step = 'sequencia' and permission in ('propor', 'executar')) >= 1), 'a permissão antiga não é necessária para autorizar o Rhetor');
select is((select count(*)::integer from private.approvals where category = 'sequencia' and agent_id = pg_temp.agente('rhetor')), 1, 'só uma proposta do Rhetor foi criada');
select ok((select exists (select 1 from pg_proc where proname = 'agent_suggest_own_sequence_template')), 'RPC de modelo próprio continua publicada');
select ok((select exists (select 1 from pg_proc where proname = 'agent_read_sequence_contacts')), 'RPC de leitura continua publicada');
select * from finish();
rollback;
